SOURCE tests/procedures/support/fixture.sql;
CALL bank_lab.sp_expect_error(DATABASE(),'request unmapped System denied','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c1,@p3_approval)',5010);
INSERT INTO DB_User_Map(db_login,actor_type,customer_id) VALUES(USER(),'Customer',@p3_c1);
SET @p3_old=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
SET @p3_other_old=(SELECT balance FROM Accounts WHERE account_id=@p3_b);
SET @p3_rows=(SELECT COUNT(*) FROM Transactions WHERE status='Completed');
CALL bank_lab.sp_expect_ok(DATABASE(),'request Customer success','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c1,@p3_approval)');
SET @p3_ok=(SELECT COUNT(*)=1 AND (SELECT balance FROM Accounts WHERE account_id=@p3_a)=@p3_old AND (SELECT balance FROM Accounts WHERE account_id=@p3_b)=@p3_other_old AND (SELECT COUNT(*) FROM Transactions WHERE status='Completed')=@p3_rows FROM Transaction_Approvals WHERE approval_id=@p3_approval AND status='Requested' AND requested_by_customer_id=@p3_c1);
CALL bank_lab.sp_assert_true(DATABASE(),'request no money moves',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'request amount 0','CALL {db}.sp_request_approval(@p3_a,@p3_b,0,NULL,@p3_c1,@p3_approval)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'request amount -1','CALL {db}.sp_request_approval(@p3_a,@p3_b,-1,NULL,@p3_c1,@p3_approval)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'request amount NULL','CALL {db}.sp_request_approval(@p3_a,@p3_b,NULL,NULL,@p3_c1,@p3_approval)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'request missing account','CALL {db}.sp_request_approval(@p3_a,-1,100000,NULL,@p3_c1,@p3_approval)',5002);
CALL bank_lab.sp_expect_error(DATABASE(),'request same account','CALL {db}.sp_request_approval(@p3_a,@p3_a,100000,NULL,@p3_c1,@p3_approval)',5005);
CALL bank_lab.sp_expect_error(DATABASE(),'request mismatched actor id','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,NULL,@p3_c2,@p3_approval)',5010);
CALL bank_lab.sp_expect_error(DATABASE(),'request both actors','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,@p3_t1,@p3_c1,@p3_approval)',5010);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL sp_set_account_status(@p3_b,'Frozen',@p3_t2);
INSERT INTO DB_User_Map(db_login,actor_type,employee_id) VALUES(USER(),'Employee',@p3_t1);
CALL bank_lab.sp_expect_error(DATABASE(),'request Frozen account','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,@p3_t1,NULL,@p3_approval)',5003);
DELETE FROM DB_User_Map WHERE db_login=USER();
CALL sp_set_account_status(@p3_b,'Active',@p3_t2);
INSERT INTO DB_User_Map(db_login,actor_type,employee_id) VALUES(USER(),'Employee',@p3_t1);
CALL bank_lab.sp_expect_ok(DATABASE(),'request Employee success','CALL {db}.sp_request_approval(@p3_a,@p3_b,100000,@p3_t1,NULL,@p3_approval)');
SET @p3_ok=(SELECT requested_by_actor_type='Employee' AND requested_by_employee_id=@p3_t1 AND requested_by_customer_id IS NULL FROM Transaction_Approvals WHERE approval_id=@p3_approval);
CALL bank_lab.sp_assert_true(DATABASE(),'request employee identity',@p3_ok,'Expected procedure contract');
DELETE FROM DB_User_Map WHERE db_login=USER();

